    /* % of 1RM clamps to 1–100 (v0.99994 behavior); unset/invalid → 75.
       S13: decimals SURVIVE the clamp (rounded to 2dp only to shed
       float noise) — percent programs step in 2.5% increments
       (67.5% is a real Juggernaut/5/3/1 load), and the old
       Math.round made every % field in the app reject them. */
    function clampPct1RM(v){const n=Number(v);return Number.isFinite(n)&&n>0?clamp(Math.round(n*100)/100,1,100):75;}

    /* Deload load clamps to 40–80%; unset/invalid → 60. Decimals
       survive, same as clampPct1RM (S13). */
    function clampDeloadPct(v){const n=Number(v);return Number.isFinite(n)&&n>0?clamp(Math.round(n*100)/100,40,80):60;}

    /* S13: a % value that is actually usable (finite, > 0), decimal-
       clamped to 1–100 — or null, so a resolution chain can fall
       through to the next source instead of landing on a default.
       (clampPct1RM's 75 default would mask every missing source.) */
    function pctValueOrNull(v){
      if(v==null||v===''||typeof v==='boolean')return null;
      const n=Number(v);
      return Number.isFinite(n)&&n>0?clamp(Math.round(n*100)/100,1,100):null;
    }

    /* S25 (Item 4, persona series 2026-10-23, issue #693): the deload
       load scale for a program week, as a percent — the ONE
       determination every surface that materializes loads shares:
       the engine's deload branch (progression.js), the session-start
       stamps (programs.js), the live editor's history ghost and the
       session context line (via forkDeloadSessionScale in
       fork-pause-queue.js). The fork mark (forkIsDeloadWeek, read
       when that module is present) scales at its fixed 60% (the
       cover's "loads at 60%"); the % wave panel's flag (isDeloadWeek,
       above) scales at the configured deloadPct (40–80, default 60;
       the program's own value beats the global default). It lives
       in the formulas layer so every load context shares it — the
       wave-flag half never depends on the fork module being loaded.
       Returns null when the week is a deload week by neither mark.
       Pure read: nothing is stored or rewritten — scaling happens
       on the per-session copies each surface presents, so the
       stored program, its template loads and the logged history
       keep the unscaled basis the next normal week derives from. */
    function forkDeloadScaleForWeek(program,week){
      if(!program||typeof program!=='object')return null;
      if(typeof forkIsDeloadWeek==='function'&&forkIsDeloadWeek(program,week))return 60;
      if(isDeloadWeek(program,week)){
        const prog=program.progression||{};
        const raw=prog.deloadPct!=null?prog.deloadPct
          :(typeof progressionSetup!=='undefined'?progressionSetup.deloadPct:undefined);
        return clampDeloadPct(Number(raw??60));
      }
      return null;
    }

    /* S13: the ONE % resolution chain for a prescribed set, shared by
       session start (programs.js) and mirrored by the preview grid:
       the set's own % of TM wins, then the exercise's % override,
       then the program's weekly wave % for the week, then the
       program's flat %, then 75. This is the engine's onermRx
       precedence (progression.js) with the per-set % slotted on top —
       a prescribed set carrying its own % overrides the weekly %. */
    function resolveSetPct(set,profile,programConfig,week){
      return pctValueOrNull(set&&set.pct)
        ?? pctValueOrNull(profile&&profile.percentOf1RM)
        ?? pctValueOrNull(programPctForWeek(programConfig,week))
        ?? pctValueOrNull(programConfig&&(programConfig.progression||programConfig).percentOf1RM)
        ?? 75;
    }
